#include "hhs_pass219_global_canonical_defaults_1_0.hpp"
#include <cassert>
int main(){using hhs::rna::CumulativePassGlobalDefaults;using hhs::rna::GlobalCanonicalDefaults;static_assert(GlobalCanonicalDefaults::numbered_passes_are_additive());static_assert(GlobalCanonicalDefaults::successful_implementations_must_remain_reachable());static_assert(!GlobalCanonicalDefaults::standalone_passes_allowed());static_assert(!GlobalCanonicalDefaults::isolated_native_project_is_canonical_substitute());static_assert(GlobalCanonicalDefaults::cross_cutting_defaults_are_mandatory());static_assert(GlobalCanonicalDefaults::retroactive_repair_forward_required());static_assert(!GlobalCanonicalDefaults::grandfather_bypass_allowed());static_assert(GlobalCanonicalDefaults::explicit_upgrade_or_deprecation_required());using P218=CumulativePassGlobalDefaults<218>;using P200C=CumulativePassGlobalDefaults<200,HHS_EXACT_PASS219_BINDING_VARIANT_C>;using P186=CumulativePassGlobalDefaults<186>;static_assert(P218::global_defaults_required&&P200C::global_defaults_required&&P186::global_defaults_required);static_assert(P218::repair_forward_on_gap&&!P218::standalone_application&&!P218::optional_cross_cutting_defaults);assert(GlobalCanonicalDefaults::validate()==HHS_EXACT_STATUS_OK);return 0;}
